1	import { existsSync } from 'fs';
2	import type { Plugin } from 'vite';
3	import { defineConfig } from 'vitest/config';
4	
5	/**
6	 * Resolves `.js` imports to `.ts` source files when both exist side-by-side.
7	 *
8	 * The NestJS monorepo keeps compiled `.js` output next to the `.ts` sources.
9	 * Without this plugin, Vite resolves `import '…/foo.js'` to the compiled JS
10	 * instead of the original TypeScript source.
11	 */
12	function resolveTypescriptSource(): Plugin {
13	  return {
14	    name: 'resolve-ts-source',
15	    enforce: 'pre',
16	    async resolveId(source, importer, options) {
17	      if (!importer) return null;
18	      const resolved = await this.resolve(source, importer, {
19	        ...options,
20	        skipSelf: true,
21	      });
22	      if (resolved && !resolved.external && resolved.id.endsWith('.js')) {
23	        const tsPath = resolved.id.replace(/\.js$/, '.ts');
24	        if (existsSync(tsPath)) return tsPath;
25	      }
26	      return null;
27	    },
28	  };
29	}
30	
31	export default defineConfig({
32	  // Spec files are excluded from every tsconfig in the repo, so Oxc cannot pick
33	  // up `experimentalDecorators`/`emitDecoratorMetadata` from them and would emit
34	  // TC39 decorators (which reject parameter decorators). Configure them here.
35	  oxc: {
36	    decorator: {
37	      legacy: true,
38	      emitDecoratorMetadata: true,
39	    },
40	    assumptions: {
41	      setPublicClassFields: true,
42	    },
43	    typescript: {
44	      removeClassFieldsWithoutInitializer: true,
45	    },
46	  },
47	  test: {
48	    globals: true,
49	    root: './',
50	    include: ['integration/**/*.spec.ts'],
