import type { FastifyError, FastifyReply, FastifyRequest } from 'fastify';

/**
 * Canonical body for an invalid batch id. It mirrors
 * {@link InvalidBatchIdException}'s plain single-message 400 exactly (same
 * key order), so both adapters - and both batch routes - serialise an
 * undecodable id segment identically.
 */
export const INVALID_BATCH_ID_BODY = {
  statusCode: 400,
  error: 'Bad Request',
  message: 'ID',
} as const;

// The two batch routes are '/batch/:id' and '/batch-plain/:id', each with a
// single (raw, still percent-encoded) path segment.
const BATCH_ID_PATH_REGEXP = /^\/batch(?:-plain)?\/[^/]+$/;

function targetsBatchIdPath(rawUrl: string | undefined): boolean {
  if (!rawUrl) {
    return false;
  }
  const questionIndex = rawUrl.indexOf('?');
  const pathname =
    questionIndex === -1 ? rawUrl : rawUrl.slice(0, questionIndex);
  return BATCH_ID_PATH_REGEXP.test(pathname);
}

/**
 * Express decodes path params lazily while matching a route. A malformed
 * percent sequence (e.g. '/batch/%zz') makes the router's `decodeParam`
 * throw a URIError (status 400, "Failed to decode param ...") before any
 * guard or pipe can run. Normalise it to the same plain 'ID' 400 that a
 * syntactically decodable but non-numeric id produces, so the Express and
 * Fastify adapters cannot be distinguished by the response. Only batch
 * routes are rewritten; every other decoding failure keeps its existing
 * path through Nest's exception layer.
 *
 * Must be registered before the application initialises (Nest mounts its
 * own exception layer during init), so this error middleware sits ahead of
 * it and can answer directly.
 */
export function batchIdDecodingErrorHandler(
  err: unknown,
  req: { url?: string },
  res: {
    status(code: number): { json(body: unknown): void };
  },
  next: (err?: unknown) => void,
): void {
  const candidate = err as
    | (URIError & { status?: number; message?: string })
    | null
    | undefined;
  const isParamDecodingFailure =
    candidate instanceof URIError ||
    (candidate?.status === 400 &&
      typeof candidate.message === 'string' &&
      candidate.message.startsWith('Failed to decode param'));

  if (isParamDecodingFailure && targetsBatchIdPath(req.url)) {
    res.status(400).json(INVALID_BATCH_ID_BODY);
    return;
  }
  next(err as unknown);
}

/**
 * Fastify (via find-my-way) rejects a request whose *path* contains a
 * malformed percent sequence before routing even starts, emitting a
 * framework-level `FST_ERR_BAD_URL` response that never reaches Nest.
 * Translate that framework error for the batch routes into the same plain
 * 'ID' 400 Express produces; every other bad URL keeps Fastify's default
 * rendering.
 */
export function batchIdFrameworkErrors(
  error: FastifyError,
  request: FastifyRequest,
  reply: FastifyReply,
): FastifyReply | void {
  if (
    error.code === 'FST_ERR_BAD_URL' &&
    targetsBatchIdPath(request.raw.url)
  ) {
    return reply.code(400).send(INVALID_BATCH_ID_BODY);
  }
  return reply.send(error);
}

