describe('PROBE9', () => {
  it('prints raw behaviors', async () => {
    const cases = [
      '/batch/%zz?item=1',
      '/batch/%?item=1',
      '/batch/%2?item=1',
      '/batch/%7?item=1',
      '/batch/%FE%FF?item=1',
      '/batch/%fe%ff?item=1',
      '/batch-plain/%zz?item=1',
      '/batch-plain/%FE%FF?item=1',
      '/batch/%37?item=%32',
      '/batch/7?item=2&tag=x&item=004',
      '/batch/%2f?item=1',
      '/other/%zz',
      '/batch/%zz/extra?item=1',
      '/batch/abc?item=x',
      '/batch/7?item=%zz&item=3',
    ];
    for (const adapter of ['express', 'fastify'] as const) {
      const app = await createAggregateParamErrorsApp(adapter);
      console.log('===', adapter, '===');
      for (const path of cases) {
        const res = await app.get(path);
        console.log(path, '=>', res.status, JSON.stringify(res.body));
      }
      await app.close();
    }
  }, 60000);
});

